export function notify(text){let region=document.getElementById('toast');if(!region){region=document.createElement('div');region.id='toast';region.role='status';document.body.append(region)}region.textContent=text;region.hidden=false;clearTimeout(region.timer);region.timer=setTimeout(()=>region.hidden=true,6500)}
export function ask(title,message,{confirm='Confirm',danger=false}={}){
 return new Promise(resolve=>{const d=document.createElement('dialog');d.className='confirm-dialog';d.setAttribute('aria-label',title);const h=document.createElement('h2');h.textContent=title;const p=document.createElement('p');p.textContent=message;const yes=document.createElement('button');yes.textContent=confirm;yes.className=danger?'danger':'primary';const no=document.createElement('button');no.textContent='Cancel';d.append(h,p,no,yes);document.body.append(d);let done=false;function finish(v){if(done)return;done=true;d.close();d.remove();resolve(v)}no.onclick=()=>finish(false);yes.onclick=()=>finish(true);d.oncancel=e=>{e.preventDefault();finish(false)};d.showModal();no.focus()})
}
export function textElement(tag,text,className){const e=document.createElement(tag);e.textContent=text;if(tag==='button')e.type='button';if(className)e.className=className;return e}
